  ('Corn_(maize)___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
  ('Grape___Black_rot', 'Bệnh thối đen trên nho', 'Lá có đốm tròn nâu đỏ, tâm nâu với các chấm đen pycnidia; quả nhiễm chuyển nâu, nhăn và hóa đen thành quả mummy.'),
  ('Grape___Esca_(Black_Measles)', 'Bệnh Esca (sởi đen) trên nho', 'Lá có sọc giữa gân kiểu ''tiger stripe'' đỏ/vàng rồi hoại tử; quả có chấm đen nhỏ viền nâu-tím (''black measles''); gỗ có vùng đổi màu/vòng đen và có thể chết cành.'),
  ('Grape___Leaf_blight_(Isariopsis_Leaf_Spot)', 'Bệnh cháy lá / đốm lá Isariopsis trên nho', 'Đốm nâu không đều đến góc cạnh trên lá, có thể 2–20 mm; bệnh nặng gây rụng lá sớm và giảm tích lũy đường/chất lượng quả.'),
  ('Grape___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
  ('Orange___Haunglongbing_(Citrus_greening)', 'Bệnh vàng lá gân xanh (Greening) trên cam', 'Chồi vàng; lá loang lổ vàng-xanh không đối xứng hai bên gân giữa, lá dày/cứng; cây suy kiệt. Quả nhỏ, lệch, chín màu không đều, giảm chất lượng và rụng.'),
  ('Peach___Bacterial_spot', 'Bệnh đốm vi khuẩn trên đào', 'Lá có đốm úng nước/góc cạnh rồi sẫm và hoại tử, có thể tạo lỗ thủng; lá vàng/rụng. Quả có đốm lõm, nứt/pitting; cành non có thể có tổn thương.'),
  ('Peach___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
  ('Pepper,_bell___Bacterial_spot', 'Bệnh đốm vi khuẩn trên ớt chuông', 'Lá có đốm nâu tròn nhỏ, viền sẫm; có thể rụng lá. Quả có đốm nâu sần/corky nhô lên, làm giảm giá trị thương phẩm.'),
  ('Pepper,_bell___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
  ('Potato___Early_blight', 'Bệnh cháy lá sớm trên khoai tây', 'Lá già xuất hiện đốm nâu có các vòng đồng tâm kiểu ''bia bắn'', mô quanh vết thường vàng; nặng các đốm liên kết làm cháy lá. Củ có thể có vết lõm sẫm với mô khô bần bên dưới.'),
  ('Potato___Late_blight', 'Bệnh cháy lá muộn trên khoai tây', 'Vết úng nước không đều trên lá, nhanh chuyển ô-liu/nâu; trong ẩm có lớp mốc trắng ở rìa/mặt dưới. Bệnh lan rất nhanh, làm cháy lá/thân. Củ có vết nâu cứng và thối bên trong.'),
  ('Potato___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
