  ('Squash___Powdery_mildew', 'Bệnh phấn trắng trên bí', 'Đốm vàng nhạt ban đầu trên lá già, sau có lớp bột trắng-xám thành mảng hoặc phủ lá; lá/cành nặng có thể héo chết, quả dễ bị cháy nắng.'),
  ('Strawberry___Leaf_scorch', 'Bệnh cháy lá trên dâu tây', 'Nhiều chấm tím đặc không có tâm trắng; mô quanh đốm đỏ/tím, mép lá dần nâu khô như bị cháy; cuống/thân lá có thể có vệt nâu-tím lõm.'),
  ('Strawberry___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.'),
  ('Tomato___Bacterial_spot', 'Bệnh đốm vi khuẩn trên cà chua', 'Lá có đốm nâu/đen nhỏ kèm quầng vàng; quả có đốm đen sần/corky lớn hơn bacterial speck, đôi khi có quầng trắng nhờn.'),
  ('Tomato___Early_blight', 'Bệnh cháy lá sớm trên cà chua', 'Lá già xuất hiện đốm nâu có các vòng đồng tâm kiểu ''bia bắn'', mô quanh vết thường vàng; nặng các đốm liên kết làm cháy lá. Thân/quả có thể có tổn thương sẫm, vòng đồng tâm; quả thường bị gần cuống.'),
  ('Tomato___Late_blight', 'Bệnh cháy lá muộn trên cà chua', 'Vết úng nước không đều trên lá, nhanh chuyển ô-liu/nâu; trong ẩm có lớp mốc trắng ở rìa/mặt dưới. Bệnh lan rất nhanh, làm cháy lá/thân. Quả có vết nâu-ô-liu lớn, cứng rồi có thể thối.'),
  ('Tomato___Leaf_Mold', 'Bệnh mốc lá trên cà chua', 'Mặt trên lá có đốm xanh nhạt–vàng không rõ viền; mặt dưới tương ứng có lớp mốc nhung ô-liu đến nâu. Lá già nhiễm trước, về sau vết liên kết, lá héo/chết.'),
  ('Tomato___Septoria_leaf_spot', 'Bệnh đốm lá Septoria trên cà chua', 'Nhiều đốm nhỏ tròn (<~3 mm) có viền sẫm và tâm nâu xám; trong tâm thường thấy chấm đen pycnidia. Bắt đầu ở lá dưới và có thể làm rụng lá mạnh.'),
  ('Tomato___Spider_mites Two-spotted_spider_mite', 'Bệnh do nhện đỏ hai chấm trên cà chua', 'Chấm trắng/vàng li ti (stippling) trên lá, lá vàng/đồng hóa và khô; mật số cao có mạng tơ mịn ở mặt dưới lá. Nhện rất nhỏ, thường có hai đốm sẫm.'),
  ('Tomato___Target_Spot', 'Bệnh đốm vòng / đốm mục tiêu trên cà chua', 'Vết lá nâu có thể có vòng đồng tâm như bia, dễ nhầm early blight/bacterial spot; bệnh nặng gây rụng lá. Thân và quả cũng có thể có đốm, làm giảm khả năng thương phẩm.'),
  ('Tomato___Tomato_Yellow_Leaf_Curl_Virus', 'Bệnh virus xoăn vàng lá cà chua', 'Lá non nhỏ, quăn lên/xuống, nhăn; vàng mép và giữa gân; cây lùn, đốt ngắn tạo dáng bụi, rụng hoa và giảm đậu quả mạnh.'),
  ('Tomato___Tomato_mosaic_virus', 'Bệnh virus khảm cà chua', 'Lá có khảm xanh nhạt–xanh đậm/vàng, biến dạng/quăn, sinh trưởng còi; quả có thể loang màu, vòng vàng hoặc vết nâu lõm tùy giống và điều kiện.'),
  ('Tomato___healthy', 'Không phát hiện bệnh thuộc lớp CV (healthy)', 'Lá không biểu hiện triệu chứng điển hình của các lớp bệnh mà model được huấn luyện để phân loại. Kết quả ''healthy'' không chứng minh cây hoàn toàn khỏe hoặc không có sâu bệnh khác.')
