  ('Apple___Apple_scab', 'LOCAL_TREATMENT_RULE_NOT_VERIFIED', FALSE, 'AGRONOMIST_ONLY_UNTIL_VN_RULE_VERIFIED', 'Không tự sinh hoạt chất, tên thuốc, liều lượng hoặc PHI.
